// Reviewed one-time import: stage in the isolated Pipeline Editor and invoke Run through Unity CLI eval.
// All sprite metadata is generated by Unity's data provider. Do not rerun over later artist edits.
using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.U2D.Sprites;
using UnityEngine;

public static class ImportNuclearExplosionAssets
{
    public const string Sheet = "Assets/Project333/Resources/Project333/SpellEffects/Nuclear/MushroomExplosion.png";
    public const string Audio = "Assets/Project333/Resources/Project333/SpellEffects/Nuclear/Audio/NuclearExplosion.wav";
    public static string Run()
    {
        ValidateSource();
        var importer = AssetImporter.GetAtPath(Sheet) as TextureImporter;
        if (importer == null) throw new InvalidOperationException("Missing staged explosion sheet.");
        var factories = new SpriteDataProviderFactories(); factories.Init();
        var provider = factories.GetSpriteEditorDataProviderFromObject(importer);
        if (provider == null) throw new InvalidOperationException("No sprite provider.");
        provider.InitSpriteEditorDataProvider();
        var capability = provider.GetDataProvider<ISpriteFrameEditCapability>();
        if (capability == null) throw new InvalidOperationException("No sprite edit capability.");
        foreach (var edit in new[] { EEditCapability.EditSpriteName, EEditCapability.EditSpriteRect,
            EEditCapability.EditPivot, EEditCapability.EditBorder, EEditCapability.CreateAndDeleteSprite })
            if (!capability.GetEditCapability().HasCapability(edit)) throw new InvalidOperationException("Unsupported sprite operation " + edit);
        var names = provider.GetDataProvider<ISpriteNameFileIdDataProvider>();
        if (names == null) throw new InvalidOperationException("No sprite-name fileID provider.");
        var prior = provider.GetSpriteRects();
        var rects = Enumerable.Range(0, 16).Select(i => {
            var name = "MushroomExplosion_" + i.ToString("00");
            var existing = prior.FirstOrDefault(s => s.name == name);
            return new SpriteRect { name = name, rect = new Rect(i % 4 * 512, (3 - i / 4) * 512, 512, 512),
                pivot = new Vector2(.5f, 32f / 512f), alignment = SpriteAlignment.Custom,
                border = Vector4.zero, spriteID = existing == null ? GUID.Generate() : existing.spriteID };
        }).ToArray();
        importer.textureType = TextureImporterType.Sprite; importer.spriteImportMode = SpriteImportMode.Multiple;
        importer.spritePixelsPerUnit = 100; importer.maxTextureSize = 2048;
        importer.npotScale = TextureImporterNPOTScale.None; importer.mipmapEnabled = false;
        importer.alphaIsTransparency = true; importer.alphaSource = TextureImporterAlphaSource.FromInput;
        importer.isReadable = false; importer.filterMode = FilterMode.Point; importer.wrapMode = TextureWrapMode.Clamp;
        importer.textureCompression = TextureImporterCompression.Uncompressed;
        // Initialize a fresh provider after switching a newly imported texture to Multiple.
        // A provider initialized in Default/Single mode otherwise ignores the multi-sprite array.
        importer.SaveAndReimport();
        provider = factories.GetSpriteEditorDataProviderFromObject(importer);
        if (provider == null) throw new InvalidOperationException("No configured sprite provider.");
        provider.InitSpriteEditorDataProvider();
        capability = provider.GetDataProvider<ISpriteFrameEditCapability>();
        if (capability == null) throw new InvalidOperationException("No configured sprite capability.");
        foreach (var edit in new[] { EEditCapability.EditSpriteName, EEditCapability.EditSpriteRect,
            EEditCapability.EditPivot, EEditCapability.EditBorder, EEditCapability.CreateAndDeleteSprite })
            if (!capability.GetEditCapability().HasCapability(edit)) throw new InvalidOperationException("Unsupported configured sprite operation " + edit);
        names = provider.GetDataProvider<ISpriteNameFileIdDataProvider>();
        if (names == null) throw new InvalidOperationException("No configured name-fileID provider.");
        provider.SetSpriteRects(rects);
        names.SetNameFileIdPairs(rects.Select(s => new SpriteNameFileIdPair(s.name, s.spriteID)).ToList());
        provider.Apply(); importer.SaveAndReimport();
        var audioImporter = AssetImporter.GetAtPath(Audio) as AudioImporter;
        if (audioImporter == null) throw new InvalidOperationException("Missing staged explosion audio.");
        audioImporter.forceToMono = false; audioImporter.loadInBackground = false;
        var audioSettings = audioImporter.defaultSampleSettings;
        audioSettings.loadType = AudioClipLoadType.DecompressOnLoad; audioSettings.compressionFormat = AudioCompressionFormat.PCM;
        audioSettings.sampleRateSetting = AudioSampleRateSetting.PreserveSampleRate; audioSettings.preloadAudioData = true;
        audioImporter.defaultSampleSettings = audioSettings; audioImporter.SaveAndReimport();
        AssetDatabase.SaveAssets();
        return Validate();
    }
    private static void ValidateSource()
    {
        var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
        try {
            if (!texture.LoadImage(File.ReadAllBytes(Sheet), false) || texture.width != 2048 || texture.height != 2048)
                throw new InvalidOperationException("Require 4x4 512px explosion cells.");
            var pixels = texture.GetPixels32();
            for (int f = 0; f < 16; f++) {
                int visible = 0, clear = 0;
                for (int y = 0; y < 512; y++) for (int x = 0; x < 512; x++) {
                    var alpha = pixels[((3 - f / 4) * 512 + y) * 2048 + f % 4 * 512 + x].a;
                    if (alpha == 0) clear++;
                    if (alpha < 16) continue;
                    visible++;
                    if (x < 16 || x > 495 || y < 16 || y > 495)
                        throw new InvalidOperationException("Explosion spills across frame " + f);
                }
                if (visible == 0 || clear == 0) throw new InvalidOperationException("Empty frame or opaque background " + f);
            }
        } finally { UnityEngine.Object.DestroyImmediate(texture); }
    }
    public static string Validate()
    {
        var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(Sheet);
        var sprites = AssetDatabase.LoadAllAssetsAtPath(Sheet).OfType<Sprite>().OrderBy(s => s.name).ToArray();
        if (texture == null || texture.width != 2048 || texture.height != 2048 || sprites.Length != 16)
            throw new InvalidOperationException("Explosion import count/dimensions mismatch.");
        for (int i = 0; i < sprites.Length; i++) {
            var s = sprites[i];
            if (s.name != "MushroomExplosion_" + i.ToString("00") || s.rect != new Rect(i % 4 * 512, (3 - i / 4) * 512, 512, 512) ||
                s.pivot != new Vector2(256, 32)) throw new InvalidOperationException("Explosion frame/pivot/order mismatch " + i);
        }
        var sound = AssetDatabase.LoadAssetAtPath<AudioClip>(Audio);
        if (sound == null || sound.channels != 1 || sound.frequency != 44100 || Math.Abs(sound.length - 1.68f) > .002f)
            throw new InvalidOperationException("Explosion cue must be mono44100 1.68s.");
        return "Nuclear explosion: 16 chronological 512px sprites; ground pivot256,32; alpha-safe containment; mono44100 PCM1.68s.";
    }
}
